-- V1__baseline_schema.sql
-- Esquema base (MySQL) generado desde las entidades JPA. Solo se ejecuta en bases VACIAS;
-- en bases existentes Flyway usa baseline-on-migrate (baseline-version 1) y lo omite.
create table attendances (attendance_date date not null, check_in_latitude DECIMAL(10,7), check_in_longitude DECIMAL(10,7), check_out_latitude DECIMAL(10,7), check_out_longitude DECIMAL(10,7), extra_hours DECIMAL(5,2), hours_worked DECIMAL(5,2), late_minutes integer, branch_id bigint not null, check_in_time datetime(6), check_out_time datetime(6), created_at datetime(6) not null, id bigint not null auto_increment, tenant_id bigint not null, updated_at datetime(6), user_id bigint not null, notes varchar(500), shift_type enum ('EVENING','MIXED','MORNING','SUNDAY') not null, status enum ('ABSENT','EXCUSED','IN_SHIFT','LATE','ON_TIME') not null, primary key (id)) engine=InnoDB;
create table audit_logs (branch_id bigint, created_at datetime(6) not null, entity_id bigint, id bigint not null auto_increment, tenant_id bigint not null, updated_at datetime(6), user_id bigint, ip_address varchar(45), entity_type varchar(50), action varchar(100) not null, details varchar(1000), primary key (id)) engine=InnoDB;
create table branches (active bit not null, latitude DECIMAL(10,7) not null, longitude DECIMAL(10,7) not null, radius_meters integer not null, tolerance_minutes integer not null, created_at datetime(6) not null, id bigint not null auto_increment, tenant_id bigint not null, updated_at datetime(6), name varchar(100) not null, address varchar(200), primary key (id)) engine=InnoDB;
create table leave_requests (end_date date not null, start_date date not null, branch_id bigint not null, created_at datetime(6) not null, id bigint not null auto_increment, reviewed_by bigint, tenant_id bigint not null, updated_at datetime(6), user_id bigint not null, admin_notes varchar(500), reason varchar(1000) not null, evidence_url varchar(255), request_type enum ('INCAPACIDAD','JUSTIFICANTE','PERMISO','VACACIONES') not null, status enum ('APPROVED','PENDING','REJECTED') not null, primary key (id)) engine=InnoDB;
create table notifications (branch_id bigint, created_at datetime(6) not null, id bigint not null auto_increment, read_at datetime(6), tenant_id bigint not null, updated_at datetime(6), icon varchar(10), recipient_role varchar(20) not null, title varchar(200) not null, body varchar(1000) not null, type enum ('CHECK_IN','CHECK_OUT','LEAVE_APPROVED','LEAVE_REJECTED','LEAVE_REQUEST','SECURITY_ALERT','SHIFT_REMINDER') not null, primary key (id)) engine=InnoDB;
create table push_subscriptions (branch_id bigint, created_at datetime(6) not null, id bigint not null auto_increment, tenant_id bigint not null, updated_at datetime(6), user_id bigint not null, role varchar(20), auth_key TEXT, endpoint TEXT not null, p256dh_key TEXT, primary key (id)) engine=InnoDB;
create table schedule_rosters (day_index integer not null, week_start date, branch_id bigint not null, created_at datetime(6) not null, id bigint not null auto_increment, tenant_id bigint not null, updated_at datetime(6), second_shift_end_time varchar(20), second_shift_start_time varchar(20), shift_end_time varchar(20), shift_start_time varchar(20), row_key varchar(50) not null, area_name varchar(100) not null, created_by varchar(100), shift_time varchar(100), target_area varchar(100), employee_name varchar(150) not null, reason varchar(255), status_type enum ('CAMBIO_AREA','CAMBIO_TURNO','DESCANSO','DOBLE_TURNO','NORMAL') not null, primary key (id)) engine=InnoDB;
create table shift_configs (created_at datetime(6) not null, id bigint not null auto_increment, tenant_id bigint not null, updated_at datetime(6), end_time varchar(10) not null, start_time varchar(10) not null, shift_name varchar(50) not null, label varchar(100) not null, days_description varchar(150), primary key (id)) engine=InnoDB;
create table tenant_modules (tenant_id bigint not null, module_name varchar(255) not null, primary key (tenant_id, module_name)) engine=InnoDB;
create table tenant_settings (tolerance_minutes integer, created_at datetime(6) not null, id bigint not null auto_increment, tenant_id bigint not null, updated_at datetime(6), primary_color varchar(20), slug varchar(50) not null, company_name varchar(150) not null, icon_url varchar(255), logo_url varchar(255), subscription_status enum ('ACTIVE','CANCELED','SUSPENDED','TRIAL'), primary key (id)) engine=InnoDB;
create table users (active bit not null, branch_id bigint, created_at datetime(6) not null, id bigint not null auto_increment, tenant_id bigint not null, updated_at datetime(6), email varchar(100), username varchar(100) not null, full_name varchar(150) not null, password varchar(255) not null, profile_picture varchar(255), role enum ('ADMIN','EMPLOYEE','SUPERUSER') not null, shift_type enum ('EVENING','MIXED','MORNING','SUNDAY'), primary key (id)) engine=InnoDB;
create index idx_att_user_date on attendances (user_id, attendance_date);
